(function(r){const C={"tracks": [{"id": "servicenow", "name": "ServiceNow", "ic": "🧩", "group": "IT", "desc": "ITSM, scripting, flows, CMDB and integrations"}, {"id": "programming", "name": "Programming & Data", "ic": "💻", "group": "IT", "desc": "JavaScript, SQL, APIs, Git and testing"}, {"id": "itfund", "name": "IT Fundamentals & Security", "ic": "🛡️", "group": "IT", "desc": "Networking, cloud and cybersecurity basics"}, {"id": "hr", "name": "HR & Recruitment", "ic": "🧑‍🤝‍🧑", "group": "Non-IT", "desc": "People, hiring, payroll and compliance"}, {"id": "finance", "name": "Finance & Accounting", "ic": "📊", "group": "Non-IT", "desc": "Accounting, statements, tax and budgets"}, {"id": "sales", "name": "Sales & Marketing", "ic": "📈", "group": "Non-IT", "desc": "Selling, digital marketing and customers"}, {"id": "ops", "name": "Operations & Supply Chain", "ic": "📦", "group": "Non-IT", "desc": "Inventory, logistics and process improvement"}, {"id": "support", "name": "Customer Support", "ic": "🎧", "group": "Non-IT", "desc": "Service skills and support operations"}, {"id": "pm", "name": "Project Management", "ic": "🗓️", "group": "Everyone", "desc": "Planning, risks, Agile and Scrum"}, {"id": "eng", "name": "Mechanical & Engineering", "ic": "⚙️", "group": "Non-IT", "desc": "Mechanics, thermodynamics, manufacturing, quality"}, {"id": "soft", "name": "Interview & Communication", "ic": "🎤", "group": "Everyone", "desc": "Self-introduction, STAR, English and workplace skills"}], "snf": {"incident": "Incident=An unplanned interruption or drop in the quality of an IT service|Priority=Calculated from impact and urgency|SLA=A target time for responding to and resolving work|Major incident=A high-impact outage handled with an urgent coordinated response|Assignment group=The team responsible for working a ticket|Resolution notes=The record of what fixed the issue and how", "problem": "Problem=The underlying cause of one or more incidents|Root cause=The fundamental reason something failed|Workaround=A temporary way to keep working until a fix exists|Known error=A problem with a documented cause and workaround|Problem task=A unit of work to investigate or fix a problem|Proactive problem management=Finding and fixing causes before incidents repeat", "change": "Standard change=A pre-approved low-risk repeatable change|Normal change=A change that needs assessment and approval|Emergency change=An urgent change to fix a serious issue with fast approval|CAB=A group that reviews and approves higher-risk changes|Rollback plan=Steps to undo a change if it fails|Change window=An agreed time when changes may be made", "cmdb": "Configuration item=Any component that must be managed such as a server or application|Relationship=A link showing how two CIs depend on each other|CI class=A category that defines the attributes of a type of CI|Discovery=A process that finds devices and populates the CMDB automatically|Reconciliation=Rules that merge duplicate data from several sources|CMDB health=Measures of completeness correctness and compliance of CMDB data", "catalog": "Catalog item=A service or product a user can request|Catalog variable=A field on a catalog item that collects requester details|Order guide=A bundle of several items requested together|Request=The overall order made by a user|Requested item=The record for one item inside a request|Fulfilment=The work done to deliver what was requested", "br": "Before rule=Runs before the record is saved and can change its values|After rule=Runs after the record is saved to act on related data|Async rule=Runs in the background so the user does not wait|Display rule=Runs when a form loads to pass data to the client|Rule condition=A filter that decides whether the rule runs|current=The object that represents the record being processed", "gr": "GlideRecord=A server-side class for querying and changing table records|addQuery=Adds a condition to the query|query=Runs the query against the database|next=Moves to the next record in the results|update=Saves changes made to the record|GlideAggregate=A class for counting and summarising records efficiently", "ui": "UI Policy=A no-code browser rule that changes field behaviour|Client Script=Browser script such as onChange or onSubmit|onChange=Runs when a field value changes|onSubmit=Runs when the form is submitted often for validation|g_form=The client API used to read and change form fields|Mandatory field=A field the user must fill in before saving", "si": "Script Include=Reusable server-side code stored once|Script Include class=A pattern with functions that a Script Include often defines|GlideAjax=Lets a client script call a server Script Include|Client callable=A setting that allows the browser to call the script|Code reuse=Calling shared code instead of copying it|Library=A collection of related helper functions", "flow": "Flow=An automated sequence of steps built without much code|Trigger=The event that starts a flow|Action=A single step such as updating a record|Subflow=A reusable flow called from other flows|Approval step=A step that waits for a person to approve or reject|Flow execution=The recorded run of a flow with its results", "rest": "GET=Reads data from a resource|POST=Creates a new resource|PUT=Replaces or updates a resource|DELETE=Removes a resource|Status 401=The caller is not authenticated|Status 404=The requested resource was not found|JSON=A lightweight text format for exchanging data", "acl": "ACL=A rule that controls access to records and fields|Role=A label that grants a set of permissions to users|Least privilege=Giving only the access that is needed|Field-level ACL=Controls access to a single field|ACL condition=A check that must be true for access|Impersonation=Testing as another user to verify their access"}, "raw": [["js", "programming", "JavaScript basics", "🟨", "javascript;js;node;typescript;react;angular", "A Swiss-army knife for the web: it runs in browsers and on servers.", "JavaScript makes web pages interactive and also runs server code. Variables hold values, functions package logic, and arrays and objects store collections. Asynchronous code lets slow tasks run without freezing the page.", "const total = prices.filter(p => p > 0).reduce((a, b) => a + b, 0);", "Use const by default, let when a value changes, and avoid var.", "Variable=A named container for a value|Function=A reusable block of code that takes inputs and returns a result|Array=An ordered list of values|Object=A collection of key and value pairs|Promise=An object representing a result that will arrive later|Callback=A function passed to another function to run later|Variable scope=The area of code where a variable can be used"], ["sql", "programming", "SQL & Databases", "🗄️", "sql;mysql;postgres;oracle;database;nosql;mongodb", "A spreadsheet that can answer questions across millions of rows.", "A relational database stores data in tables of rows and columns. SQL reads and changes it: SELECT reads, INSERT adds, UPDATE changes and DELETE removes. JOIN combines tables and an index makes searches faster.", "SELECT city, COUNT(*) FROM orders GROUP BY city;", "Always filter with WHERE before you UPDATE or DELETE.", "Primary key=A column that uniquely identifies each row|Foreign key=A column that links to the primary key of another table|JOIN=Combines rows from two tables using a related column|WHERE=Filters rows by a condition|GROUP BY=Groups rows so totals can be calculated|Index=A structure that speeds up searches on a column|Normalization=Organising data to reduce duplication"], ["api", "programming", "APIs & HTTP", "🔗", "api;rest;http;json;postman;swagger;microservice", "A waiter between the kitchen and your table.", "An API is a contract that lets one program ask another for data or actions. Requests go to an endpoint with a method such as GET or POST, and the response carries a status code and usually JSON.", "GET /users/42 returns the profile of user 42 as JSON.", "Name the method, the endpoint and the status code when you explain an API call.", "API=A defined way for software to talk to other software|HTTP method=The action requested such as GET or POST|Endpoint=The URL where an API can be reached|Header=Extra information sent with a request such as authentication|Authentication=Proving who the caller is|Rate limit=A cap on how many requests are allowed in a time period|Status code=A number showing the outcome of a request"], ["git", "programming", "Git & Version Control", "🌿", "git;github;gitlab;bitbucket;version control", "A time machine for your project that also lets a team work in parallel.", "Git records every change as a commit so you can go back and compare. Branches let people work separately, and a pull request lets others review before the work is merged.", "Create a branch, commit your fix, open a pull request, merge after review.", "Write commit messages that say why, not just what.", "Repository=A project folder with its full history|Commit=A saved snapshot of changes with a message|Branch=A separate line of work|Merge=Combining changes from one branch into another|Pull request=A request for others to review changes before merging|Merge conflict=When two changes touch the same lines and need manual resolution|Clone=A full local copy of a repository"], ["qa", "programming", "Testing & QA", "🧪", "testing;qa;selenium;test case;automation testing;manual testing;uat", "A safety net that catches problems before customers do.", "Testing checks that software does what it should. Unit tests check small parts, integration tests check parts together, and regression tests make sure old features still work. Good bug reports let anyone reproduce the problem.", "Test case: enter a wrong password, expect a clear error message.", "A good bug report has steps, expected result, actual result and evidence.", "Unit test=Checks one small piece of code in isolation|Integration test=Checks that parts work together|Regression testing=Re-testing to make sure old features still work|Test case=Steps with expected results used to verify a feature|Bug report=A clear record of a defect with steps to reproduce|UAT=User acceptance testing by the business before release|Test automation=Using tools to run tests without manual effort"], ["net", "itfund", "Networking basics", "🌐", "network;tcp;dns;dhcp;router;vpn;lan;networking", "The postal system of the internet: addresses, sorting offices and roads.", "Devices on a network are identified by IP addresses. DNS turns names into addresses, routers move traffic between networks, firewalls filter it, and VPNs protect it over the internet.", "Typing a website name triggers a DNS lookup, then your request travels through routers to the server.", "Explain with the postal analogy: address, sorting, delivery.", "IP address=A number that identifies a device on a network|DNS=Translates domain names into IP addresses|Router=Directs traffic between networks|Firewall=Filters traffic based on security rules|VPN=An encrypted tunnel over the internet|Bandwidth=The amount of data that can be sent in a given time|DHCP=Automatically assigns IP addresses to devices"], ["cloud", "itfund", "Cloud basics", "☁️", "aws;azure;gcp;cloud;docker;kubernetes;saas", "Renting electricity instead of owning a power plant.", "Cloud providers rent computing over the internet. IaaS gives raw servers, PaaS gives a platform to run apps, and SaaS gives finished software. You pay for what you use and can scale up or down quickly.", "A company runs its website on rented virtual machines and adds more during a sale.", "Know the difference between IaaS, PaaS and SaaS by heart.", "IaaS=Rented infrastructure such as virtual servers|PaaS=A platform for building apps without managing servers|SaaS=Ready-to-use software delivered over the internet|Virtual machine=A software computer running on shared hardware|Scalability=Ability to handle more load by adding resources|Region=A geographic area where cloud data centres are located|Container=A lightweight package of an app and its dependencies"], ["sec", "itfund", "Cybersecurity basics", "🔐", "security;cyber;siem;vulnerability;penetration;iso 27001;infosec", "Locks, guards and alarms for your digital house.", "Security protects people, data and systems. Most attacks start with people, such as phishing, so training matters. Layers like multi-factor sign-in, encryption and regular patching reduce the damage of any single failure.", "An employee reports a suspicious email, and the security team blocks the sender.", "Say layers: no single control is enough.", "Phishing=A fake message that tricks people into giving information|Multi-factor authentication=Using more than one proof of identity to sign in|Encryption=Scrambling data so only authorised people can read it|Malware=Software designed to cause harm|Zero trust=Never trust automatically and always verify every request|Patch management=Applying updates to fix known security flaws|Vulnerability=A weakness that could be exploited"], ["hrf", "hr", "HR fundamentals", "🧑‍💼", "human resources;hr executive;hr manager;hr generalist;hris;employee relations;talent management;workday;sap hr", "HR is the bridge between people and the business.", "HR manages the employee lifecycle: attracting, hiring, developing, rewarding and retaining people. It also keeps the company compliant with labour laws and builds a healthy culture.", "An HR team runs onboarding, answers policy questions, supports payroll and handles grievances.", "Show that you balance employee interests with business goals.", "Employee lifecycle=The stages from hiring to exit|HRIS=A system that stores employee data and HR processes|Job description=A document listing duties and requirements of a role|Employee engagement=How committed and motivated people feel at work|Grievance handling=A fair process for resolving employee complaints|Attrition=The rate at which employees leave an organisation|Exit interview=A conversation to learn why someone is leaving"], ["rec", "hr", "Recruitment & onboarding", "📝", "recruit;talent acquisition;sourcing;screening;onboarding;naukri;linkedin recruiter;ats;hiring", "Recruiting is matchmaking: the right person, the right role, the right time.", "Recruitment starts with a clear job description, then sourcing, screening, interviews, offer and background checks. Onboarding helps the new hire become productive and stay.", "Source candidates, screen by phone, schedule interviews, send an offer, then run a first-week plan.", "Quote numbers: time to hire, offers accepted, source quality.", "Sourcing=Finding potential candidates before they apply|Screening=Reviewing candidates to see who meets the basic requirements|Behavioural interview=Questions about past actions to predict future behaviour|Offer letter=A formal document stating the job terms offered|Background verification=Checking a candidate's claims such as education and past jobs|Onboarding=Helping a new hire settle in and become productive|Time to hire=Days from opening a role to an accepted offer"], ["hrp", "hr", "Performance & compliance", "📋", "payroll;appraisal;performance management;compliance;labour law;pf;esi;gratuity", "Fair pay and clear feedback keep a workplace running smoothly.", "HR sets goals, reviews performance and manages payroll accurately and on time. Compliance means following labour laws and company policy so employees are protected and the company avoids penalties.", "A manager sets KPIs, reviews them at appraisal time, and payroll applies the approved increment.", "Accuracy and confidentiality are the two words to stress in payroll roles.", "KPI=A measurable value that shows progress toward a goal|Appraisal=A formal review of an employee's performance|PIP=A plan to help an underperforming employee improve|Payroll=Calculating and paying salaries, deductions and benefits|Provident fund=A retirement savings scheme funded by employee and employer|Gratuity=A benefit paid to employees after long service|Policy compliance=Following laws and company rules"], ["acc", "finance", "Accounting basics", "🧮", "accounting;tally;bookkeeping;accounts payable;accounts receivable;general ledger;sap fico;ledger", "Accounting is the scoreboard of a business.", "Every transaction affects at least two accounts, so debits equal credits. Assets are what a business owns, liabilities what it owes, and equity what remains for owners. Accrual accounting records items when earned or incurred.", "Buying goods on credit increases inventory (debit) and creditors (credit).", "Remember the equation: Assets = Liabilities + Equity.", "Asset=Something of value that a business owns|Liability=An amount a business owes|Equity=The owners' share after liabilities are paid|Debit=An entry on the left side of an account|Credit=An entry on the right side of an account|Accrual accounting=Recording items when earned or incurred not when cash moves|Depreciation=Spreading the cost of an asset over its useful life"], ["fs", "finance", "Financial statements", "📑", "financial statements;balance sheet;p&l;profit and loss;cash flow;mis report;financial reporting;ebitda", "Three reports tell the whole story: what you have, what you earned, and where the cash went.", "The balance sheet is a snapshot of assets, liabilities and equity. The profit and loss statement shows performance over a period. The cash flow statement shows real cash movement, which can differ from profit.", "A company can be profitable on paper yet short of cash if customers pay late.", "Explain the difference between profit and cash with one example.", "Balance sheet=A snapshot of assets, liabilities and equity at a date|Profit and loss statement=Shows revenue, expenses and profit over a period|Cash flow statement=Shows cash moving in and out of the business|Gross profit=Revenue minus the direct cost of goods sold|EBITDA=Earnings before interest, tax, depreciation and amortisation|Working capital=Current assets minus current liabilities|Net profit margin=Net profit as a percentage of revenue"], ["tax", "finance", "Tax, audit & banking", "🏦", "gst;tds;income tax;audit;reconciliation;budgeting;forecasting;fp&a;invoice", "Rules, checks and plans that keep money honest.", "Finance teams file taxes on time, reconcile accounts with the bank, prepare budgets and compare them with actual results. Audits check that controls work and records are reliable.", "Reconcile the bank statement each month and explain any difference before closing the books.", "Mention deadlines and controls: they show you take accuracy seriously.", "GST=A tax on the supply of goods and services|TDS=Tax deducted at source when certain payments are made|Bank reconciliation=Matching company records with the bank statement|Budget=A plan for expected income and spending|Variance analysis=Comparing actual results with the budget to explain gaps|Internal audit=An independent check that controls and processes work properly|Invoice=A bill requesting payment for goods or services"], ["sal", "sales", "Sales process", "🤝", "sales;lead generation;business development;b2b;cold calling;pipeline;quota;negotiation", "Selling is solving a problem for someone, not pushing a product.", "A sale moves from lead to qualified lead, then to a proposal and closing. Good sellers ask questions to understand the need, handle objections with facts and empathy, and follow up consistently.", "Call a lead, learn their budget and timeline, send a proposal, handle price concerns, then close.", "Ask more questions than you answer, and quote your quota achievement.", "Lead=A person or company that may become a customer|Qualified lead=A lead that fits the need, budget and timing|Sales pipeline=The stages a deal moves through before closing|Objection handling=Responding to a buyer's concerns with facts and empathy|Closing=Getting the buyer to agree and commit|Quota=A sales target for a person or team in a period|Conversion rate=The share of leads that become customers"], ["dm", "sales", "Digital marketing", "📣", "seo;sem;digital marketing;google ads;social media;content marketing;email marketing;analytics", "Marketing is being useful in the places your customers already look.", "Digital marketing attracts people through search, social media, email and content. SEO earns free traffic, SEM buys it, and analytics shows which efforts lead to conversions and at what cost.", "Publish a helpful guide, promote it with ads, and track clicks, sign-ups and cost per sign-up.", "Tie every channel to a number: clicks, leads or cost per customer.", "SEO=Improving a site to rank higher in unpaid search results|SEM=Paid advertising on search engines|CTR=The percentage of people who click after seeing an ad|CPC=The cost paid for each click on an ad|Conversion=A desired action such as a purchase or sign-up|Content marketing=Creating useful material to attract and keep an audience|Customer acquisition cost=The cost of winning one new customer"], ["crm", "sales", "CRM & customer relationships", "💬", "crm;salesforce;hubspot;customer relationship;account management;retention;customer success", "Keeping a customer is cheaper than finding a new one.", "A CRM stores every interaction so teams know the history. Strong account managers measure retention and churn, ask for feedback, and grow accounts with relevant upsell and cross-sell offers.", "A renewal is at risk, so the account manager schedules a review and fixes the open issues.", "Mention retention and satisfaction results to show long-term thinking.", "CRM=A system that tracks customer interactions and deals|Churn=The rate at which customers stop buying|Retention=Keeping existing customers over time|NPS=A score of how likely customers are to recommend you|Upsell=Selling a higher-value version to an existing customer|Cross-sell=Selling a related product to an existing customer|Customer lifetime value=The total value a customer brings over time"], ["sc", "ops", "Supply chain basics", "🚚", "supply chain;logistics;inventory;procurement;warehouse;sap mm;vendor management;purchasing", "A supply chain is a relay race: every handover must be smooth.", "A supply chain moves goods from suppliers to customers. Teams balance stock levels against cost, plan from demand forecasts, and choose suppliers and carriers carefully so products arrive on time.", "Raise stock orders early for a supplier with a long lead time and keep safety stock.", "Use numbers: stock-outs avoided, cost saved, on-time delivery.", "Inventory=Goods a business holds for sale or production|Lead time=Time between placing an order and receiving it|Safety stock=Extra inventory kept to cover uncertainty|Just-in-time=Receiving goods only when needed to cut storage|Procurement=The process of sourcing and buying goods and services|3PL=A third-party company that handles logistics|Demand forecasting=Estimating future customer demand"], ["lean", "ops", "Process improvement", "♻️", "lean;six sigma;kaizen;5s;process improvement;sop;operations;continuous improvement", "Great operations remove waste so people can do the valuable work.", "Process improvement finds waste and variation and removes them. Lean focuses on flow and waste, Six Sigma on defects, and Kaizen on small daily improvements. Standard procedures keep the gains.", "Map a slow approval process, find the bottleneck, remove one step and write a new SOP.", "Tell a before and after story with numbers.", "Lean=A method of removing waste while delivering value|Six Sigma=A data-driven approach to reduce defects and variation|Kaizen=Continuous small improvements by everyone|5S=Sort, set in order, shine, standardise and sustain|Bottleneck=The step that limits the speed of the whole process|SOP=A written standard operating procedure|DMAIC=Define, measure, analyse, improve and control"], ["cs", "support", "Customer service skills", "🎧", "customer service;customer support;call centre;bpo;chat support;helpdesk;customer care", "Every call is a chance to turn a problem into loyalty.", "Good service listens first, shows empathy, solves the problem clearly and follows up. When a customer is upset, calm them before fixing. When you cannot solve it, escalate with full details.", "A delayed order: apologise, check the status, give a new date, and send an update.", "Use the pattern: listen, empathise, solve, confirm.", "Empathy=Understanding and acknowledging how the customer feels|Listening to confirm=Focusing fully and confirming what you heard|First contact resolution=Solving the issue in the first interaction|CSAT=A score of how satisfied customers are after an interaction|De-escalation=Calming an upset customer before solving the problem|Escalation=Passing a case to a higher level when you cannot resolve it|Service recovery=Fixing a bad experience so the customer stays"], ["sup", "support", "Support operations", "🛠️", "ticketing;zendesk;freshdesk;l1;l2;knowledge base;aht;sla", "A well-run help desk is a calm kitchen at rush hour.", "Support teams log every request in a ticketing system and work it by priority. First-line staff solve common issues, harder cases go to second line, and knowledge articles let customers help themselves.", "A password reset is solved by L1 in minutes; a server fault goes to L2 with notes.", "Know your metrics: handle time, backlog, CSAT and SLA.", "Ticketing system=A tool that records and tracks customer requests|L1 support=First-line team handling common questions|L2 support=A more technical team handling complex cases|Knowledge base=A library of articles that answer common questions|Average handle time=The average time spent on one interaction|Backlog=Open requests waiting to be worked|SLA breach=Missing the agreed response or resolution time"], ["pm", "pm", "Project management basics", "🗓️", "project management;pmp;prince2;stakeholder;gantt;ms project;jira;project plan", "A project is a promise: this outcome, by this date, within this budget.", "Project managers define scope, break work into tasks, plan time and cost, manage risks and keep stakeholders informed. The critical path shows which tasks can delay the finish.", "Define scope, build a WBS, set milestones, track risks weekly and report status to stakeholders.", "Describe how you handled a change in scope or a risk that came true.", "Scope=The work that is included in a project|WBS=Breaking the project into smaller deliverables|Milestone=A key point that marks progress|Stakeholder=Anyone affected by or interested in the project|Risk register=A list of risks with their impact and plans|Critical path=The longest chain of tasks that sets the project end date|Baseline=The approved plan used to measure progress"], ["agile", "pm", "Agile & Scrum", "🔄", "agile;scrum;sprint;kanban;product owner;scrum master;scaled agile", "Build a little, learn a lot, repeat.", "Agile delivers value in short cycles and adapts to feedback. In Scrum the team works in sprints from a prioritised backlog, meets daily, demos the result and holds a retrospective to improve.", "A two-week sprint: plan, daily stand-ups, demo to stakeholders, retrospective.", "Explain the roles and ceremonies in one breath, then add an example.", "Sprint=A short fixed period to finish a set of work|Product backlog=An ordered list of everything the product might need|Daily stand-up=A brief daily team sync|Retrospective=A meeting to learn how to work better|Velocity=The amount of work a team finishes in a sprint|Product owner=Decides what is most valuable to build|Scrum master=Helps the team follow Scrum and removes blockers"], ["mech", "eng", "Mechanical fundamentals", "🔧", "mechanical;thermodynamics;cad;solidworks;autocad;catia;design engineer;hvac;fluid mechanics", "Engineering is physics with a deadline and a budget.", "Mechanical engineers apply forces, energy and materials to design parts and machines. Stress and strain describe how materials respond to load, and a factor of safety keeps designs reliable. Heat moves by conduction, convection and radiation.", "A shaft is sized so stress stays well below the material strength with a factor of safety.", "Walk through your calculation steps aloud: assumptions, formula, result.", "Stress=Force applied per unit area inside a material|Strain=How much a material deforms relative to its original length|Torque=A turning force around an axis|Factor of safety=Ratio of material strength to the expected load|First law of thermodynamics=Energy cannot be created or destroyed only converted|Conduction=Heat transfer through direct contact|Convection=Heat transfer by the movement of fluids"], ["mfg", "eng", "Manufacturing & quality", "🏭", "manufacturing;cnc;quality;production;maintenance;iso 9001;spc;welding;gd&t", "Quality is built into the process, not inspected in at the end.", "Manufacturing turns designs into parts using processes such as machining, casting and welding. Tolerances define acceptable variation, preventive maintenance avoids breakdowns, and quality tools find and remove the causes of defects.", "A rising reject rate leads to root cause analysis, a mistake-proofing fix and an updated check sheet.", "Describe a defect you reduced and the number before and after.", "CNC machining=Computer-controlled cutting of parts|Tolerance=The allowed variation in a dimension|GD&T=A symbol system describing allowed geometry variation|Preventive maintenance=Planned servicing to avoid breakdowns|Statistical process control=Using data charts to keep a process stable|Root cause analysis=Finding the real reason behind a defect|Poka-yoke=Mistake-proofing a process so errors cannot happen"], ["intro", "soft", "Self-introduction & STAR", "🎤", "self introduction;star method;interview skills;presentation;elevator pitch", "Your introduction is the trailer of your career: short, clear, and it makes them want more.", "A strong self-introduction follows present, past, future: who you are now, what you have done and what you want next. For behavioural questions use STAR: Situation, Task, Action, Result, and spend most of your time on the action and result.", "I'm a payroll executive with three years of experience. Earlier I ... Now I'm looking to ...", "Keep your introduction to about 60 seconds and end with your goal.", "Present past future=A structure for self-introductions|STAR method=Situation, Task, Action, Result for behavioural answers|Elevator pitch=A short persuasive summary of who you are|Quantified result=An outcome with a number that proves impact|Ownership language=Saying I did instead of we when describing your role|Closing question=A thoughtful question you ask at the end of an interview|Follow-up email=A thank-you note sent within a day of the interview"], ["hrq", "soft", "Common HR questions", "❓", "interview questions;hr round;salary negotiation;career gap", "Every HR question is really asking: will you fit, will you grow, will you stay?", "HR rounds test attitude and fit. Prove strengths with examples, show a real weakness you are fixing, give a researched salary range, explain gaps honestly and never criticise a former employer.", "Weakness: I used to avoid delegating. Now I assign tasks with clear deadlines and it has saved me hours.", "Prepare a one-line answer plus one proof for each common question.", "Strengths answer=Pick strengths that fit the job and prove them with an example|Weakness answer=Name a real weakness and show how you are improving it|Why-hire-you answer=Match your skills and results to their need|Salary answer=Give a researched range and stay flexible|Career gap answer=Explain honestly then show what you learned or did|Reason-for-leaving answer=Focus on growth and never criticise the old employer|Five-year goal answer=Show growth in the field and commitment to the company", true], ["comm", "soft", "Communication & English tips", "🗣️", "communication skills;english;public speaking;email etiquette;soft skills", "Clear speaking is a skill you can train like a muscle.", "Speak in short clear sentences, pause between ideas and avoid filler sounds. Listen fully before answering, paraphrase to confirm and match your tone and body language to your words.", "Instead of um I think maybe, pause, then say: The main reason is ...", "Practise aloud with the Speak tab and record your pace.", "Active listening=Focusing fully and confirming what you heard|Paraphrasing=Repeating the idea in your own words to confirm understanding|Filler words=Sounds like um and uh that weaken a message|Pace=Speaking not too fast and pausing between ideas|Tone=The attitude your voice and words convey|Body language=Posture, eye contact and gestures that support your words|Professional email=A clear subject, short paragraphs, a polite tone and a clear next step"], ["work", "soft", "Workplace skills", "🤲", "teamwork;leadership;time management;problem solving;adaptability;critical thinking;collaboration", "Skills get you hired; habits keep you growing.", "Employers value people who cooperate, manage time, handle conflict calmly, accept feedback and take initiative. Show these with short real stories rather than adjectives.", "Two urgent tasks arrive: ask the manager for priority, plan the day and communicate the timeline.", "Replace adjectives with proof: a number, a name, an outcome.", "Teamwork=Working with others toward a shared goal|Conflict resolution=Finding a solution that respects both sides|Time management=Planning and prioritising work to meet deadlines|Eisenhower matrix=Sorting tasks by urgent and important|Constructive feedback=Specific kind input aimed at improvement|Adaptability=Adjusting quickly to change|Initiative=Acting without waiting to be told"]], "scen": {"incident": ["The payment page is down for 400 customers during peak hours.", "Confirm the impact and set priority 1; declare a major incident; assemble the on-call team; communicate status to stakeholders every 30 minutes; restore service with a workaround or rollback first; record every action; after recovery raise a problem for the root cause"], "problem": ["The same login failure has been logged 25 times this month.", "Link the incidents to one problem record; analyse logs and recent changes for the root cause; share a workaround with the service desk; raise a change to apply the permanent fix; keep a known error until it is fixed"], "change": ["You must upgrade a production database over the weekend.", "Raise a normal change with a risk assessment; test in a lower environment; prepare a rollback plan; get approval from the change board; communicate the change window; implement and validate; close with a review"], "cmdb": ["Two teams report different owners for the same server.", "Check the discovery and import sources; use reconciliation rules to merge duplicates; set the authoritative source; assign a CI owner; add data health checks and regular audits"], "catalog": ["Employees ask for new laptops by email and requests get lost.", "Create a catalog item with variables for model and manager; add an approval step; build a flow to fulfil the request and notify the user; publish it in the portal; report on fulfilment time"], "br": ["Priority must be set automatically when impact and urgency are both high.", "Create a before insert and update business rule on the incident table; add a condition for high impact and urgency; set the priority on current; avoid calling update inside a before rule; test with sample records"], "gr": ["A script must close every resolved incident older than 30 days.", "Create a GlideRecord on the incident table; add queries for resolved state and the age condition; call query; loop with next; set the state; call update; limit the batch and test on a few records first"], "ui": ["The close notes field must be mandatory only when the state is Resolved.", "Use a UI policy with the condition state is Resolved; set the field mandatory and visible; use a client script only if the logic is more complex; test on the form"], "si": ["Five business rules repeat the same manager lookup code.", "Move the lookup into a script include class with a function; call it from each rule; keep it server-side; test it once; avoid copy and paste"], "flow": ["Laptop requests above a cost limit must go to a manager for approval.", "Trigger the flow on the requested item; add a condition on the cost; add an approval step for the manager; update the record and send a notification; add error handling and test with real data"], "rest": ["Syncing new incidents to an external system fails with a 401 response.", "Check the credentials or token and whether it expired; confirm the authentication type; test the call in a REST client; log the response; fix the connection record; add a retry and an alert"], "acl": ["A user cannot edit the Assigned to field but should be able to.", "Impersonate the user; check the ACLs on the table and the field; check the required roles; check conditions and scripts; fix the ACL following least privilege; retest"], "js": ["A web form must validate the email address before submit.", "Read the field value; test it with a pattern; show a clear error message; prevent the submit when invalid; test valid and invalid inputs"], "sql": ["You need the number of orders per city for last month.", "Use SELECT with city and COUNT; filter the date range in WHERE; GROUP BY city; order by the count; check that the date column has an index if it is slow"], "api": ["Your app receives 429 responses from an API.", "A 429 means you are rate limited; slow down the requests; add a retry with backoff; cache results; check the provider limits; log and alert"], "git": ["Two developers changed the same lines and the merge failed.", "Pull the latest branch; open the conflicting files; decide the correct combined code; mark the conflict resolved; run the tests; commit the merge"], "qa": ["Users report that checkout crashes sometimes.", "Collect the steps, device and logs; reproduce the problem; write a bug report with expected and actual results; add a regression test after the fix; retest"], "net": ["A user can reach the internet but not the company site by name.", "Test by IP address; if that works suspect DNS; check the DNS settings and flush the cache; try another DNS server; check the firewall; confirm and document the fix"], "cloud": ["Traffic spikes during a sale and the site slows down.", "Scale out with more instances or auto scaling; use a load balancer; cache content; monitor metrics; set limits and alerts; review the cost afterwards"], "sec": ["An employee clicked a suspicious link.", "Report it immediately; isolate the device; reset the password and sessions; check logs for malicious activity; scan for malware; share lessons with staff"], "hrf": ["An employee complains about a manager's behaviour.", "Listen and keep it confidential; document the facts; follow the grievance policy; investigate fairly with both sides; decide and communicate the outcome; follow up and prevent retaliation"], "rec": ["A critical role has been open for 60 days.", "Review the job description and salary range; widen the sourcing channels; use referrals; speed up the interview steps; keep candidates informed; track time to hire"], "hrp": ["Payroll shows a wrong deduction for an employee.", "Verify the inputs and the policy; compare with the previous month; correct the entry; process an adjustment; inform the employee; add a check to prevent a repeat"], "acc": ["The trial balance does not balance.", "Check that debits equal credits; look for one-sided entries and transposed numbers; review recent postings; correct with adjusting entries; rerun the trial balance"], "fs": ["The company shows a profit but has no cash.", "Check receivables and inventory growth; review the cash flow statement; chase late payments; negotiate payment timing with suppliers; forecast cash weekly"], "tax": ["The bank balance and the ledger differ at month end.", "List the unmatched items; separate timing differences such as uncleared cheques; correct errors; post adjustments; sign off the reconciliation"], "sal": ["A prospect says your price is higher than a competitor's.", "Ask what they are comparing; restate the value and results; show the total cost of ownership; offer options or a smaller package; ask for the next step"], "dm": ["Ad clicks are high but sign-ups are low.", "Check that the landing page matches the ad; test the headline and form length; review traffic quality; track the conversion rate; run an A/B test; adjust the budget"], "crm": ["A key customer may not renew.", "Review their usage and tickets; contact them to understand concerns; fix open issues; show value with results; offer a suitable plan; track the renewal risk in the CRM"], "sc": ["A key supplier is late and stock is running low.", "Check the stock cover; contact the supplier for a firm date; expedite or find an alternate supplier; use safety stock; prioritise key customers; update the demand plan"], "lean": ["Approvals take five days and customers complain.", "Map the process; measure the time at each step; find the bottleneck; remove or combine steps; pilot the change; update the SOP and track cycle time"], "cs": ["A customer is angry about a double charge.", "Listen fully; apologise and empathise; verify the charge; start the refund or correction; confirm the timing; follow up and record the case"], "sup": ["The backlog doubled after a product release.", "Triage by priority; write a knowledge article for the common issue; create a reply template; add temporary staff to the queue; report to the product team; track the backlog and SLA"], "pm": ["A stakeholder asks for extra features in the middle of the project.", "Record it as a change request; assess the impact on time, cost and risk; discuss the options; get sponsor approval; update the plan and baseline; communicate the decision"], "agile": ["The team keeps missing its sprint goals.", "Review it in the retrospective; check story sizing and carried-over work; reduce work in progress; protect the sprint from new work; use velocity to plan"], "mech": ["A bracket cracks under repeated load.", "Suspect fatigue; check stress concentrations and load cycles; inspect the material and surface; redesign with fillets or a stronger material; test it; apply a factor of safety"], "mfg": ["The reject rate rises on a machined part.", "Check the measurements against tolerance; inspect tool wear and setup; use control charts; find the root cause with five whys; fix it and add mistake-proofing; verify the rate falls"], "intro": ["You are asked: tell me about yourself.", "Start with your current role and strengths; add one or two key experiences with a result; finish with what you want next; keep it to about a minute"], "hrq": ["You are asked about your biggest weakness.", "Choose a real, non-critical weakness; give a short example; explain the steps you are taking; show progress; never claim to have no weakness"], "comm": ["You feel nervous and use many filler words.", "Prepare short answers; pause instead of saying um; slow your pace; practise aloud and record yourself; breathe before you answer"], "work": ["Two teammates disagree and the work is blocked.", "Listen to both separately; find the shared goal; agree on the facts; propose a compromise; confirm the actions; follow up"]}, "open": [{"c": "HR", "q": "Tell me about yourself.", "k": ["currently", "experience", "skills", "previously", "achievement", "looking", "goal"], "m": "Use present, past, future: your current role, key experience and one achievement, then what you want next."}, {"c": "HR", "q": "What are your strengths?", "k": ["strength", "example", "result", "skill", "team", "helped"], "m": "Pick two strengths relevant to the job and prove each with a short example and a result."}, {"c": "HR", "q": "What is your biggest weakness?", "k": ["weakness", "improving", "learned", "working on", "feedback", "course"], "m": "Name a real, non-critical weakness, then explain the steps you are taking and the progress you have made."}, {"c": "HR", "q": "Why should we hire you?", "k": ["skills", "experience", "result", "value", "fit", "need", "contribute"], "m": "Match your skills and results to their need, then say what you will contribute in the first months."}, {"c": "HR", "q": "Why do you want to leave your current job?", "k": ["growth", "learn", "opportunity", "challenge", "new", "skills", "positive"], "m": "Stay positive: you want growth, new challenges and to use your skills more fully. Never criticise your employer."}, {"c": "HR", "q": "Where do you see yourself in five years?", "k": ["grow", "learn", "lead", "goal", "company", "skills", "contribute"], "m": "Show ambition tied to this field and this company: deeper skills, more responsibility and real contribution."}, {"c": "HR", "q": "What are your salary expectations?", "k": ["range", "market", "research", "flexible", "experience", "value", "negotiat"], "m": "Give a researched range based on market and experience, say you are flexible, and focus on the whole role."}, {"c": "HR", "q": "Can you explain the gap in your resume?", "k": ["gap", "learned", "course", "family", "upskill", "ready", "returned"], "m": "Be honest and brief, then show what you learned or did in that time and that you are ready now."}, {"c": "HR", "q": "What do you know about our company?", "k": ["research", "products", "mission", "values", "customers", "news", "role", "fit"], "m": "Mention what they do, their customers or recent news, and connect it to why the role fits you."}, {"c": "HR", "q": "What is your greatest achievement?", "k": ["result", "impact", "number", "challenge", "team", "action", "recognition"], "m": "Choose one achievement with a number, explain the challenge, your action and the impact."}, {"c": "HR", "q": "Why did you choose this career?", "k": ["interest", "passion", "skills", "learn", "impact", "experience", "goal"], "m": "Share a genuine reason, an early experience, and how your interest has grown into skills."}, {"c": "HR", "q": "How do you stay updated in your field?", "k": ["learn", "course", "read", "community", "practice", "certif", "news"], "m": "Name specific habits: courses, reading, communities, practice projects and certifications."}, {"c": "HR", "q": "What motivates you?", "k": ["learn", "goal", "impact", "team", "growth", "challenge", "recognition"], "m": "Connect motivation to useful work: solving problems, learning, helping the team and seeing results."}, {"c": "HR", "q": "Do you have any questions for us?", "k": ["team", "success", "growth", "expectations", "challenges", "next steps", "culture"], "m": "Ask about success in the role, the team, challenges and next steps. Avoid asking only about salary or leave."}, {"c": "Behavioural", "q": "Tell me about a time you worked in a team to achieve a goal.", "k": ["team", "situation", "task", "action", "result", "communicate", "goal"], "m": "Use STAR: the situation and goal, your task, what you did to help the team, and the measurable result."}, {"c": "Behavioural", "q": "Tell me about a conflict with a colleague and how you handled it.", "k": ["listen", "understand", "calm", "solution", "compromise", "result", "respect"], "m": "Describe the conflict neutrally, how you listened and found a shared solution, and the improved outcome."}, {"c": "Behavioural", "q": "Describe a time you failed or made a mistake.", "k": ["mistake", "learned", "fix", "responsib", "improve", "next time", "result"], "m": "Own the mistake, explain how you fixed it, what you learned and how you prevent it now."}, {"c": "Behavioural", "q": "Tell me about a time you worked under pressure or a tight deadline.", "k": ["prioritis", "plan", "deadline", "focus", "team", "delivered", "calm"], "m": "Explain how you prioritised, planned, communicated and delivered, with the result."}, {"c": "Behavioural", "q": "Describe a time you showed leadership.", "k": ["lead", "motivate", "delegate", "goal", "result", "team", "decision"], "m": "Show how you guided others without needing a title: direction, support, decisions and results."}, {"c": "Behavioural", "q": "How do you handle criticism or feedback?", "k": ["listen", "feedback", "improve", "learn", "thank", "action", "not personal"], "m": "Listen, thank them, ask for examples, act on it and share a real example of improving."}, {"c": "Behavioural", "q": "Tell me about a time you went above and beyond.", "k": ["extra", "initiative", "customer", "result", "ownership", "impact"], "m": "Describe the situation, the extra effort you chose to make, and the impact for the customer or team."}, {"c": "Behavioural", "q": "How do you prioritise when you have many tasks?", "k": ["urgent", "important", "deadline", "plan", "list", "impact", "communicate"], "m": "Rank by urgency and impact, plan the day, communicate with stakeholders and re-check priorities."}, {"c": "Situational", "q": "A customer is angry about a delay. What do you do?", "k": ["listen", "apolog", "empathy", "solution", "update", "follow", "escalat"], "m": "Listen, apologise, show empathy, give a clear solution and timeline, and follow up. Escalate if needed."}, {"c": "Situational", "q": "You disagree with your manager's decision. What do you do?", "k": ["listen", "understand", "data", "respect", "discuss", "private", "support"], "m": "Seek to understand, raise concerns privately with facts, respect the final decision and support it."}, {"c": "Situational", "q": "You realise you made a mistake that nobody has noticed. What do you do?", "k": ["admit", "tell", "fix", "impact", "prevent", "honest", "manager"], "m": "Be honest: tell your manager quickly, explain the impact, fix it and add a check to prevent it."}, {"c": "Situational", "q": "Two urgent tasks arrive at the same time. How do you decide?", "k": ["prioritis", "impact", "deadline", "ask", "communicate", "manager", "plan"], "m": "Check impact and deadlines, ask your manager if unclear, communicate timelines and plan the order."}, {"c": "Situational", "q": "A new team member is struggling. How do you help?", "k": ["help", "listen", "train", "patient", "pair", "feedback", "resources"], "m": "Listen to the problem, pair up, share resources, give patient feedback and check progress."}, {"c": "Situational", "q": "You are given a task you have never done before. What is your approach?", "k": ["learn", "ask", "research", "plan", "small", "feedback", "practice"], "m": "Research, ask experienced colleagues, break the task into steps, start small and ask for feedback."}, {"c": "Situational", "q": "A deadline will be missed because of something outside your control. What do you do?", "k": ["communicate", "early", "options", "plan", "stakeholder", "impact", "solution"], "m": "Tell stakeholders early, explain the cause and impact, offer options and a revised plan."}], "tech": {"hr": [{"q": "Walk me through your recruitment process from job description to offer.", "k": ["job description", "sourcing", "screening", "interview", "offer", "background", "onboarding"], "m": "Clarify the role, source and screen candidates, run interviews, make the offer, verify and onboard."}, {"q": "How do you handle a grievance raised by an employee?", "k": ["listen", "confidential", "investigate", "fair", "policy", "resolve", "follow"], "m": "Listen, keep it confidential, investigate fairly, apply policy, resolve and follow up."}], "finance": [{"q": "Explain the difference between profit and cash flow.", "k": ["profit", "cash", "accrual", "receivable", "timing", "statement"], "m": "Profit includes items earned or incurred, while cash flow shows real money moving. Late customer payments can make a profitable company short of cash."}, {"q": "How would you do a bank reconciliation?", "k": ["bank statement", "ledger", "match", "difference", "timing", "adjust", "report"], "m": "Match the ledger to the bank statement, identify differences such as timing items, adjust errors and report the reconciled balance."}], "sales": [{"q": "How do you handle a customer who says your price is too high?", "k": ["value", "understand", "budget", "benefit", "compare", "alternative", "close"], "m": "Understand the concern, reinforce value and benefits, compare with alternatives, and offer options before closing."}, {"q": "How do you build and manage your sales pipeline?", "k": ["lead", "qualify", "follow", "stage", "target", "forecast", "crm"], "m": "Generate and qualify leads, follow up consistently, track stages in a CRM and forecast against target."}], "ops": [{"q": "How would you reduce delivery delays in a supply chain?", "k": ["bottleneck", "supplier", "forecast", "inventory", "communicate", "data", "improve"], "m": "Find the bottleneck with data, improve forecasting, align suppliers, hold safety stock and communicate clearly."}, {"q": "Describe a process improvement you led.", "k": ["problem", "data", "root cause", "change", "result", "sop", "measure"], "m": "Describe the problem, data and root cause, the change you made, the measured result and the new SOP."}], "support": [{"q": "How do you handle a customer who is shouting?", "k": ["calm", "listen", "apolog", "empathy", "solution", "escalat", "follow"], "m": "Stay calm, let them finish, apologise and empathise, then solve or escalate and follow up."}, {"q": "How do you balance speed with quality on calls?", "k": ["handle time", "resolution", "quality", "checklist", "knowledge", "customer", "first contact"], "m": "Use knowledge articles and checklists to resolve first time, since quality reduces repeat contacts."}], "pm": [{"q": "How do you handle scope creep?", "k": ["scope", "change request", "impact", "stakeholder", "approve", "document", "communicate"], "m": "Document changes, assess impact on time and cost, get stakeholder approval and update the plan."}, {"q": "How do you manage project risks?", "k": ["risk", "register", "probability", "impact", "mitigat", "owner", "review"], "m": "Identify risks, rate probability and impact, plan mitigation, assign owners and review regularly."}], "eng": [{"q": "Describe how you would find the root cause of a recurring machine failure.", "k": ["data", "root cause", "inspect", "why", "maintenance", "test", "prevent"], "m": "Collect data, inspect, ask why repeatedly, test the cause, fix it and add preventive maintenance."}, {"q": "How do you choose a material for a component?", "k": ["strength", "cost", "weight", "corrosion", "load", "temperature", "standard"], "m": "Consider load, strength, weight, corrosion, temperature, cost and standards, then validate with testing."}], "programming": [{"q": "Explain the difference between a GET and a POST request.", "k": ["get", "post", "read", "create", "body", "idempotent", "status"], "m": "GET reads data and has no body; POST creates data and sends a body. GET is safe to repeat while POST usually is not."}, {"q": "How do you debug a bug you cannot reproduce?", "k": ["logs", "steps", "environment", "data", "reproduce", "hypothesis", "test"], "m": "Gather logs, steps and environment details, form hypotheses, test them one by one and add monitoring."}], "itfund": [{"q": "How would you respond to a phishing email reported by an employee?", "k": ["report", "block", "investigate", "reset", "awareness", "logs", "contain"], "m": "Contain it, investigate and block the sender, reset affected passwords, check logs and raise awareness."}, {"q": "Explain what happens when you type a website address in a browser.", "k": ["dns", "ip", "request", "server", "response", "browser", "render"], "m": "DNS finds the IP address, the browser sends a request, the server responds and the browser renders the page."}]}};if(typeof module!=="undefined"&&module.exports)module.exports=C;else r.CONTENT=C;})(typeof window!=="undefined"?window:globalThis);
